// Generates the NFR-PERF-1 CSV benchmark fixture (task 7.7; R1.3, R27.11, AT-CSV-01).
//
// Output: test/fixtures/csv/benchmark-10k.csv, exactly 10,000 data rows plus one header row,
// exactly 10 columns, 0 invalid rows under the import rules (oversellPolicy REJECT, currencies
// USD and EUR, portfolio pf-bench). The content is fully determined by a fixed-seed generator,
// so the committed file can be regenerated byte for byte:
//
//   node scripts/generate-csv-fixture.mjs           writes the fixture
//   node scripts/generate-csv-fixture.mjs --check   exits 1 if the committed file differs
//
// Rows: unique external ids; 50 tickers (even index USD, odd index EUR, one currency each);
// strictly increasing UTC timestamps; a SELL only for at most half the quantity already bought
// earlier in the file, so no row is an oversell. Quantities and prices are generated as scaled
// integers and written as decimal text; the script does no arithmetic on decimal values.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import process from 'node:process';
import { URL, fileURLToPath } from 'node:url';

const OUTPUT = new URL('../test/fixtures/csv/benchmark-10k.csv', import.meta.url);
const ROWS = 10_000;
const TICKERS = 50;
const HEADER = 'external_id,portfolio_id,trade_timestamp,ticker,type,quantity,price,currency,venue,note';
const VENUES = ['XNYS', 'XNAS', 'XETR', 'XLON'];
const START_MS = Date.UTC(2026, 0, 5, 9, 30, 0);

/** Park-Miller minimal standard generator with a fixed seed: deterministic integers. */
function generator(seed) {
  let state = seed;
  return (bound) => {
    state = (state * 48_271) % 2_147_483_647;
    return state % bound;
  };
}

/** Scaled integer (4 decimal places) as decimal text, for example 125000 -> "12.5000". */
const scaled4 = (units) => `${Math.trunc(units / 10_000)}.${String(units % 10_000).padStart(4, '0')}`;

export function generateFixture() {
  const next = generator(20_261_107);
  const held = new Array(TICKERS).fill(0); // scaled quantity units per ticker
  const lines = [HEADER];
  for (let i = 0; i < ROWS; i += 1) {
    const t = next(TICKERS);
    const ticker = `T${String(t).padStart(3, '0')}`;
    const currency = t % 2 === 0 ? 'USD' : 'EUR';
    const sell = held[t] >= 20_000 && next(4) === 0;
    const units = sell ? 10_000 + next(Math.trunc(held[t] / 2) - 9_999) : 10_000 + next(990_000);
    held[t] += sell ? -units : units;
    const cents = 100 + next(99_900);
    const price = `${Math.trunc(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
    const timestamp = new Date(START_MS + i * 7_000).toISOString();
    const venue = VENUES[next(VENUES.length)];
    const note = `"Batch ${next(1_000)}, desk ""A"""`;
    lines.push(
      [
        `bench-${String(i + 1).padStart(5, '0')}`,
        'pf-bench',
        timestamp,
        ticker,
        sell ? 'SELL' : 'BUY',
        scaled4(units),
        price,
        currency,
        venue,
        note,
      ].join(','),
    );
  }
  return `${lines.join('\n')}\n`;
}

const isMain = process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const text = generateFixture();
  const sha = createHash('sha256').update(text, 'utf8').digest('hex');
  if (process.argv.includes('--check')) {
    let committed;
    try {
      committed = readFileSync(OUTPUT, 'utf8');
    } catch {
      committed = undefined;
    }
    if (committed !== text) {
      process.stderr.write('benchmark-10k.csv differs from the generator output.\n');
      process.exit(1);
    }
    process.stdout.write(`benchmark-10k.csv matches the generator (sha256 ${sha}).\n`);
  } else {
    writeFileSync(OUTPUT, text, 'utf8');
    process.stdout.write(`wrote benchmark-10k.csv (${ROWS} rows, sha256 ${sha}).\n`);
  }
}
